import csv, collections
rows=list(csv.DictReader(open('galaxy_outputs/score_summary.tsv'), delimiter='\\t'))
# convert
for r in rows:
    r['count']=int(r['count']); r['mean_score']=float(r['mean_score']); r['n_gt0.5']=int(r['n_gt0.5'])
for typ in ['horizontal_cell','RPE_cell','endothelial_cell','fibroblast','Pericyte','Schwann_cell','astrocyte','microglial_cell','macrophage','T_cells','B_cell']:
    print('\\n###',typ)
    for sample in ['s1','s2']:
        sel=[r for r in rows if r['type']==typ and r['sample']==sample]
        sel.sort(key=lambda r:r['mean_score'], reverse=True)
        print(sample, 'total_n_gt0.5', sum(r['n_gt0.5'] for r in sel))
        for r in sel[:8]:
            if r['mean_score']>0.03 or r['n_gt0.5']>0:
                print(' ',r['cluster'],'count',r['count'],'mean',r['mean_score'],'n>0.5',r['n_gt0.5'])
PY"
